/* 独立设计探索：所有视图和交互仅使用 data.js 的 Mock。无业务接口请求。 */
(() => {
const d=structuredClone(window.EXPLORATION_DATA), number=new Intl.NumberFormat('en-US'), scheme=document.body.dataset.scheme
const meta=window.CONCEPTS.find(s=>s.id===scheme), state={scope:0,period:7}, labels={2:'待接单',3:'备餐中',4:'待取餐',5:'已完成'}
const paths={leaf:'M20 4C10 3 3 6 4 14s12 8 16-10ZM5 20 15 10',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',orders:'M8 3h8v4H8zM6 5H4v17h16V5h-2M8 12h8M8 17h5',dish:'M3 13h18M5 13a7 7 0 0 1 14 0M12 4v2M3 18h18',chat:'M4 4h16v12H9l-5 4zM8 8h8M8 12h5',arrow:'M5 12h14M13 6l6 6-6 6',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',screen:'M3 4h18v13H3zM8 21h8M12 17v4',clock:'M12 7v6l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',more:'M4 12h1M11 12h1M18 12h1',check:'m4 12 5 5L20 6',bell:'M4 17h16l-2-3V9A6 6 0 0 0 6 9v5ZM10 21h4',down:'m6 9 6 6 6-6',expand:'M14 3h7v7M21 3l-9 9M3 8v13h13v-6'}
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`
const fmt=n=>number.format(n), money=n=>number.format(n.toFixed?Number(n.toFixed(2)):n), w=id=>d.windows.find(x=>x.id===id), rows=()=>d.orders.filter(o=>!state.scope||o.windowId===state.scope).sort((a,b)=>a.startTime.localeCompare(b.startTime)||b.id.localeCompare(a.id))
const metrics=()=>state.scope?w(state.scope):d.summary
const filteredSales=()=>d.sales.filter(x=>!state.scope||x.windowId===state.scope)
const brand=()=>`<a class="brand" href="../index.html"><span class="brand-symbol">${icon('leaf',23)}</span><span>禾序<span class="brand-en">HEXU CANTEEN</span></span></a>`
const nav=(kind='vertical')=>`<nav class="nav ${kind}" aria-label="工作导航">${[['grid','经营概览','overview'],['orders','预约订单','orders'],['dish','菜品与库存','menu'],['chat','学生反馈','feedback']].map(([i,l,a])=>`<button class="nav-item ${a==='overview'?'active':''}" data-nav="${a}" title="${l}">${icon(i)}<span>${l}</span>${a==='orders'?`<small>${metrics().pending}</small>`:''}</button>`).join('')}</nav>`
const account=()=>`<div class="account"><span class="avatar">禾</span><span>食堂管理员<small>全校管理权限</small></span><button class="icon-btn" data-action="account" aria-label="查看管理员信息">${icon('down',14)}</button></div>`
const utility=()=>`<div class="utilities"><button class="screen-link" data-nav="screen">${icon('screen',16)}<span>运营数据大屏</span>${icon('expand',13)}</button><button class="icon-btn" data-action="search" title="查找预约 / 快捷键 /">${icon('search')}</button>${account()}</div>`
const controls=()=>`<div class="filters"><label class="scope-label">管理范围<select aria-label="管理范围" data-scope><option value="0" ${!state.scope?'selected':''}>全校食堂</option>${d.windows.map(x=>`<option value="${x.id}" ${state.scope===x.id?'selected':''}>${x.canteenName} · ${x.name}</option>`).join('')}</select></label><span class="date">2026.11.05　周四</span><button class="btn" data-action="export">导出概览 ${icon('arrow',14)}</button></div>`
const heading=(title='经营概览',desc='从容经营，好好照顾每一餐。')=>`<header class="page-heading"><div><span class="eyebrow">${meta.tag} / ${meta.id}</span><h1>${title}</h1><p>${desc}</p></div>${controls()}</header>`
const side=(small=false)=>`<aside class="sidebar ${small?'rail':''}">${brand()}<div class="workspace">${icon('dish',20)}<span>校园餐饮工作区<small>全校食堂</small></span>${icon('down',12)}</div>${nav()}<div class="sidebar-bottom"><span class="sync-dot"></span>原型 · 示例数据<a href="../index.html">返回设计画廊 ${icon('arrow',14)}</a></div></aside>`
const top=()=>`<header class="topbar">${brand()}${nav('horizontal')}${utility()}</header>`
const kpi=(label,key,foot='',cls='')=>`<article class="kpi ${cls}"><span>${label}</span><strong>${key==='revenue'?'<em>¥</em>':''}${fmt(metrics()[key])}<small>${key==='revenue'?'.00':' '}</small></strong><p>${foot}</p></article>`
const kpis=()=>`<div class="kpi-strip">${kpi('累计核销收入','revenue','仅统计已完成取餐订单')}${kpi('今日预约','todayOrders','当前范围 · 当日预约笔数')}${kpi('待接单','pending','支付完成后进入待接单','clickable')}${kpi('累计已完成','completed','核销后记入经营表现')}</div>`
const panel=(title,sub,content,cls='',action='')=>`<section class="panel ${cls}"><header class="panel-head"><div><span class="eyebrow">${sub}</span><h2>${title}</h2></div>${action||`<button class="icon-btn" data-action="explain" aria-label="查看${title}说明">${icon('more')}</button>`}</header>${content}</section>`
// 坐标标签用HTML保持实际字号，绘图区用SVG随容器缩放，防止小图刻度变成难读的小字。
function trend(kind='area',compact=false){
 const factor=state.scope?metrics().revenue/d.summary.revenue:1,values=(state.period===14?[...d.previous,...d.trend]:d.trend).map(x=>Math.round(x*factor)),names=state.period===14?['10/23','10/24','10/25','10/26','10/27','10/28','10/29',...d.dates]:d.dates
 const width=700,height=200,pad=12,max=Math.ceil(Math.max(...values)/500)*500,base=height-8,points=values.map((v,i)=>[pad+i*(width-pad*2)/(values.length-1),base-v/max*(height-20)])
 const line=points.map((p,i)=>`${i?'L':'M'}${p[0]},${p[1]}`).join(' ')
 const bars=values.map((v,i)=>{const bw=(width-pad*2)/values.length*.45,x=pad+i*(width-pad*2)/values.length;return `<rect class="trend-bar" x="${x}" y="${base-v/max*(height-20)}" width="${bw}" height="${v/max*(height-20)}" rx="${kind==='sticks'?0:4}" fill="${i===values.length-1?'var(--accent)':'var(--chart-soft)'}"><title>${names[i]}：¥${fmt(v)}</title></rect>`}).join('')
 return `<div class="chart-caption"><strong>¥ ${fmt(values.reduce((a,b)=>a+b,0))}<small>范围内核销金额</small></strong><div class="segmented" aria-label="图表时间范围">${[7,14].map(n=>`<button class="${state.period===n?'active':''}" data-period="${n}">${n} 天</button>`).join('')}</div></div><div class="chart-wrap ${compact?'compact-chart':''}"><div class="y-labels">${[1,.5,0].map(t=>`<span>${Number((max*t/1000).toFixed(2))}k</span>`).join('')}</div><div class="plot-region"><svg class="trend" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="核销金额趋势，单位元"><g class="chart-grid">${[0,.5,1].map(t=>`<line x1="12" y1="${base-t*(height-20)}" x2="688" y2="${base-t*(height-20)}"/>`).join('')}</g>${['bar','sticks'].includes(kind)?bars:`${kind==='area'?`<path d="${line} L${points.at(-1)[0]},${base} L12,${base} Z" fill="var(--chart-soft)" opacity=".5"/>`:''}<path class="trend-line" d="${line}" stroke="var(--accent)" fill="none" stroke-width="${kind==='editorial'?2:3}" vector-effect="non-scaling-stroke"/>`}</svg>${['bar','sticks'].includes(kind)?'':`<div class="chart-markers">${points.map((p,i)=>`<span class="chart-point" tabindex="0" style="left:${p[0]/width*100}%;top:${p[1]/height*100}%" data-tip="${names[i]} · ¥${fmt(values[i])}" aria-label="${names[i]}核销金额${values[i]}元"></span>`).join('')}</div>`}</div><div class="x-labels">${names.filter((n,i)=>i%(state.period===14?2:1)===0).map(n=>`<span>${n}</span>`).join('')}</div></div>`
}

const queue=()=>`<div class="queue-total"><strong>${metrics().pending+metrics().preparing+metrics().ready}</strong><span>笔预约处理中</span></div><div class="queue-breakdown">${[['pending','待接单',2],['preparing','备餐中',3],['ready','待取餐',4]].map(([key,label,s])=>`<button data-status="${s}"><span class="status-dot s${s}"></span><span>${label}</span><b>${metrics()[key]}</b>${icon('arrow',14)}</button>`).join('')}</div>`
const sales=(images=false)=>`<div class="sales-list">${filteredSales().slice(0,4).map((s,i)=>`<button class="sale-row" data-dish="${s.id}"><span class="rank">0${i+1}</span>${images?`<img src="../assets/${s.image}.jpg" alt="${s.name}"/>`:''}<span class="sale-info"><b>${s.name}</b><span class="rank-track"><i style="width:${s.value/268*100}%"></i></span></span><strong>${s.value}<small>份</small></strong></button>`).join('')}</div>`
const recent=(limit=4)=>`<div class="recent-list">${rows().slice(0,limit).map(o=>`<button class="recent-row" data-order="${o.id}"><span class="avatar">${o.studentName[0]}</span><span><b>${o.studentName}</b><small>${w(o.windowId).name} · ${o.startTime} – ${o.endTime}</small></span><b class="amount">¥${o.amount.toFixed(2)}</b><span class="badge s${o.status}">${labels[o.status]}</span>${icon('arrow',13)}</button>`).join('')}</div>`
const orderTable=()=>`<div class="table-wrap"><table><thead><tr><th>预约 / 学生</th><th>窗口</th><th>取餐时段</th><th class="numeric">金额</th><th>状态</th><th></th></tr></thead><tbody>${rows().slice(0,5).map(o=>`<tr><td><b>${o.studentName}</b><small>${o.id}</small></td><td>${w(o.windowId).name}</td><td class="mono">${o.startTime} – ${o.endTime}</td><td class="numeric">¥${o.amount.toFixed(2)}</td><td><span class="badge s${o.status}">${labels[o.status]}</span></td><td><button class="icon-btn" data-order="${o.id}" aria-label="查看${o.studentName}的预约">${icon('arrow',16)}</button></td></tr>`).join('')}</tbody></table></div>`
const attention=()=>`<div class="attention"><button data-status="2"><span class="attention-icon">${icon('orders')}</span><span><b>${metrics().pending} 笔预约等待接单</b><small>已支付，等待窗口开始备餐</small></span>${icon('arrow',16)}</button><button data-nav="menu"><span class="attention-icon warm">${icon('dish')}</span><span><b>${filteredSales().filter(s=>s.stock<10).length} 道菜品库存偏低</b><small>余量小于 10 份，建议关注</small></span>${icon('arrow',16)}</button><button data-nav="feedback"><span class="attention-icon">${icon('chat')}</span><span><b>${d.feedback.filter(f=>(!state.scope||f.windowId===state.scope)&&!f.reply).length} 条学生反馈未回复</b><small>查看窗口建议与就餐反馈</small></span>${icon('arrow',16)}</button></div>`
// 品类数量直接由当前窗口的菜品核销样本聚合，避免筛选后仍展示全校比例。
const mix=()=>{const cats=d.preferences.map((c,i)=>({...c,i,value:filteredSales().filter(s=>s.category===c.name).reduce((sum,s)=>sum+s.value,0)})).filter(c=>c.value),total=cats.reduce((sum,c)=>sum+c.value,0);return `<div class="mix-bar">${cats.map(c=>`<span style="flex:${c.value};background:var(--mix${c.i})" title="${c.name} ${c.value}份"></span>`).join('')}</div><div class="mix-legend">${cats.map(c=>`<span><i style="background:var(--mix${c.i})"></i>${c.name}<b>${(c.value/total*100).toFixed(1)}%</b></span>`).join('')}</div>`}

function occupancy(){return `<div class="occupancy"><div class="slot-head"><span>窗口 / 时段</span>${d.slots.map(s=>`<span>${s.time}</span>`).join('')}</div>${d.windows.filter(x=>!state.scope||x.id===state.scope).map(x=>`<div class="slot-row"><b>${x.name}</b>${d.slots.map(s=>`<button class="slot-cell level${Math.ceil(s.reserved[x.id-1]/s.capacity[x.id-1]*3)}" data-slot="${s.time}" title="${x.name} ${s.time}：已约${s.reserved[x.id-1]} / 容量${s.capacity[x.id-1]}">${s.reserved[x.id-1]}<small>/${s.capacity[x.id-1]}</small></button>`).join('')}</div>`).join('')}</div>`}
const windowMatrix=()=>`<div class="load-legend"><span><i></i>待接单</span><span><i></i>备餐中</span><span><i></i>待取餐</span></div><div class="window-matrix">${d.windows.map(x=>`<button data-window="${x.id}" class="window-matrix-row ${state.scope===x.id?'selected':''}"><span class="window-letter">${x.id.toString().padStart(2,'0')}</span><span><small>${x.canteenName}</small><b>${x.name}</b></span><span class="window-stack"><span class="window-fill" style="width:${(x.pending+x.preparing+x.ready)/Math.max(...d.windows.map(a=>a.pending+a.preparing+a.ready))*100}%"><i style="flex:${x.pending}"></i><i style="flex:${x.preparing}"></i><i style="flex:${x.ready}"></i></span></span><span><strong>${x.pending+x.preparing+x.ready}</strong><small>处理中</small></span>${icon('arrow',16)}</button>`).join('')}</div>`
function kanban(){return `<div class="kanban">${[2,3,4].map(s=>`<section class="lane"><header><span class="status-dot s${s}"></span><b>${labels[s]}</b><strong>${metrics()[{2:'pending',3:'preparing',4:'ready'}[s]]}</strong></header>${rows().filter(o=>o.status===s).map(o=>`<article class="ticket"><div class="ticket-head"><small>${o.id}</small><span>${o.startTime}</span></div><h3>${o.studentName}<small>${w(o.windowId).name}</small></h3><p>${o.items}</p><div class="ticket-note">${o.remark}</div><footer><strong>¥${o.amount.toFixed(2)}</strong><button data-order="${o.id}">${s===2?'接单详情':s===3?'备餐详情':'取餐详情'} ${icon('arrow',14)}</button></footer></article>`).join('')}<button class="lane-all" data-status="${s}">查看${labels[s]}预约 ${icon('arrow',14)}</button></section>`).join('')}</div>`}
const graphPanel=(kind='area',compact=false)=>panel('核销金额趋势',`近${state.period===7?'七':'十四'}日 · 同一业务口径`,trend(kind,compact),'trend-panel')
const revenue=()=>kpi('累计核销收入','revenue','已完成取餐后计入 · 非下单金额','hero-kpi')
const overviewInfo=()=>`<div class="overview-note">统计口径：收入按已取餐订单计，未支付预约不进入待接单队列。</div>`
const layouts={
'01':()=>`${side()}<div class="shell"><header class="slim-top"><span class="breadcrumb">工作区 / 全校食堂</span>${utility()}</header><main>${heading()}<div class="grove-grid"><div class="revenue-panel">${revenue()}<div class="mini-pair">${kpi('今日预约','todayOrders','笔预约')}${kpi('累计核销','completed','笔订单')}</div></div>${panel('把等待变成一餐好饭','订单处理',queue(),'queue-panel')}${graphPanel()}${panel('热门菜品','已完成取餐 · 销量',sales(),'sales-panel')}${panel('近期预约','正在进行',recent(),'recent-panel',`<button class="text-btn" data-nav="orders">全部预约 ${icon('arrow',14)}</button>`)}${panel('品类偏好','按核销份数',mix(),'mix-panel')}</div>${overviewInfo()}</main></div>`,
'02':()=>`${top()}<main class="service-main">${heading('午餐现场','先处理正在等待的预约，再从容看经营。')}${kpis()}<div class="service-grid"><div>${panel('预约处理台','三阶段 · 同一份订单样本',kanban(),'board-panel',`<button class="btn" data-nav="orders">全部预约 ${icon('arrow',14)}</button>`)}</div><aside>${panel('需要关注','当前管理范围',attention(),'attention-panel')}${graphPanel('bar',true)}${panel('受欢迎的菜品','核销销量',sales(),'sales-panel')}</aside></div>${overviewInfo()}</main>`,
'03':()=>`<aside class="editorial-rail">${brand()}<span class="vertical-word">CAMPUS OPERATIONS / 2026</span><a href="../index.html" title="返回设计画廊">${icon('arrow')}</a></aside><div class="ledger-shell"><header class="ledger-top">${nav('horizontal')}${utility()}</header><main>${heading('一日经营，心中有序。','禾序运营手记 / 周四 · 校园窗口经营记录')}<div class="ledger-numbers">${revenue()}${kpi('今日预约','todayOrders','记录每一份期待')}${kpi('待接单','pending','需要及时回应')}${kpi('累计核销','completed','已完成取餐')}</div>${graphPanel('editorial')}<div class="ledger-bottom">${panel('预约台账','今日 · 处理中的预约',orderTable(),'table-panel')}${panel('好味道排行榜','核销份数 TOP 04',sales(),'sales-panel')}</div>${overviewInfo()}</main></div>`,
'04':()=>`${side()}<div class="quiet-shell"><header class="quiet-top"><span>工作区　/　经营概览</span>${utility()}</header><main>${heading('今天的工作','2026 年 11 月 5 日，周四')}${kpis()}<div class="quiet-grid"><div>${panel('预约队列','先处理已付款预约',orderTable(),'table-panel',`<button class="text-btn" data-nav="orders">查看全部 ${icon('arrow',14)}</button>`)}${panel('需要处理','三个明确的下一步',attention(),'flat-attention')}</div><aside>${panel('经营速览','近七日核销',trend('line',true),'trend-panel')}${panel('窗口状态','进行中预约',queue(),'queue-panel')}${panel('菜品销量','TOP 04',sales(),'sales-panel')}</aside></div>${overviewInfo()}</main></div>`,
'05':()=>`<header class="float-header">${brand()}${utility()}</header><main class="float-main">${heading('一切，都在好好发生。','你的食堂经营画布')}<div class="float-grid"><div class="revenue-panel">${revenue()}<span class="leaf-watermark">${icon('leaf',90)}</span>${kpi('今日预约','todayOrders','当前管理范围')}</div>${graphPanel('area')}${panel('正在处理','预约队列',queue(),'queue-panel')}${panel('好味道，值得再来','已核销销量',sales(true),'sales-panel')}${panel('品类偏好','当前范围 · 核销份数',mix(),'mix-panel')}${panel('近期预约','取餐时间顺序',recent(3),'recent-panel')}</div></main><div class="dock">${nav('horizontal')}</div>`,
'06':()=>`${side(true)}<div class="night-shell"><header class="night-top"><span class="night-title">运营值守 / <b>全校食堂</b></span>${utility()}</header><main>${heading('经营监测','有序接单，明确每一笔预约的下一步。')}${kpis()}<div class="night-grid">${panel('预约处理队列','已支付 · 进行中',orderTable(),'table-panel')}${panel('当前状态','三阶段预约队列',queue(),'queue-panel')}${graphPanel('bar',true)}${panel('窗口负载','按待接单 / 备餐 / 待取餐区分',windowMatrix(),'matrix-panel')}${panel('低库存与反馈','当前范围提醒',attention(),'attention-panel')}</div>${overviewInfo()}</main></div>`,
'07':()=>`${top()}<div class="campus-layout"><aside class="campus-picker"><span class="eyebrow">WINDOWS</span><h2>校园窗口</h2><button class="campus-all ${!state.scope?'selected':''}" data-window="0">全校总览 ${icon('grid',16)}</button>${d.windows.map(x=>`<button class="campus-location ${state.scope===x.id?'selected':''}" data-window="${x.id}"><small>${x.canteenName}</small><b>${x.name}</b><span>${x.pending+x.preparing+x.ready} 笔处理中 ${icon('arrow',13)}</span></button>`).join('')}<div class="campus-key"><i></i>绿色表示当前查看范围</div></aside><main>${heading('跨窗口，从容调度。','按窗口比较正在进行的预约，及时关注库存与反馈。')}<div class="campus-grid">${panel('窗口负载比较','同一时刻 · 订单状态',windowMatrix(),'matrix-panel')}${panel('管理范围汇总','当前范围',`${revenue()}<div class="mini-pair">${kpi('今日预约','todayOrders','笔')}${kpi('待接单','pending','笔')}</div>`,'campus-summary')}${panel('取餐时段占用','已预约 / 容量 · Mock',occupancy(),'occupancy-panel')}${graphPanel('line',true)}${panel('近期预约','按管理范围过滤',recent(3),'recent-panel')}${panel('受欢迎的菜品','核销份数',sales(),'sales-panel')}</div>${overviewInfo()}</main></div>`,
'08':()=>`${top()}<main class="tempo-main">${heading('今天的取餐节奏','围绕时间与窗口，让高峰有序流动。')}<div class="tempo-kpis">${revenue()}<div>${kpi('今日预约','todayOrders','笔预约')}${kpi('待接单','pending','笔需处理')}${kpi('已完成','completed','累计核销')}</div></div><div class="tempo-grid"><div>${panel('午餐取餐计划','11:00 — 13:00 / 已约数与窗口容量',occupancy(),'occupancy-panel',`<span class="pill">20 分钟 / 时段</span>`)}<div class="tempo-bottom">${graphPanel('line',true)}${panel('菜单表现','热门菜品',sales(),'sales-panel')}</div></div><aside>${panel('下一批预约','当前范围 · 进行中',recent(4),'recent-panel')}${panel('需要关注','在高峰前处理',attention(),'attention-panel')}</aside></div>${overviewInfo()}</main>`,
'09':()=>`<header class="signal-top">${brand()}<span class="workspace-name">校园经营工作区</span>${nav('horizontal')}${utility()}</header><main class="signal-main">${heading('把注意力，留给重要的事。','从当前数据中找到下一步。这里的提示按固定规则生成。')}<form class="command" data-command><span>${icon('search',22)}</span><input aria-label="查找工作" name="query" placeholder="查找预约、菜品、库存或学生反馈…" autocomplete="off"/><kbd>/</kbd><button class="primary" type="submit">打开工作 ${icon('arrow',17)}</button></form><div class="signal-grid"><section class="signal-inbox"><div class="section-label">需要你关注 <span>03</span></div>${attention()}<div class="rule-note">${icon('check',16)}规则提示 · 根据订单状态与库存计算</div>${panel('近期预约','需要上下文时再展开',recent(3),'recent-panel')}</section><div class="signal-context"><div class="context-top"><span>当前经营上下文</span><span class="pill">Mock</span></div><div class="signal-metrics">${revenue()}${kpi('今日预约','todayOrders','笔预约')}${kpi('累计核销','completed','笔订单')}</div>${graphPanel('line',true)}${panel('热门菜品','用于安排备餐优先级',sales(),'sales-panel')}</div></div>${overviewInfo()}</main>`,
'10':()=>`<header class="pantry-masthead">${brand()}${nav('horizontal')}${utility()}</header><main class="pantry-main">${heading('每一餐，经营有方。','禾序食堂 · 今日经营简报')}<div class="pantry-grid"><aside class="pantry-ledger">${revenue()}<div class="pantry-stats">${kpi('今日预约','todayOrders','笔预约')}${kpi('累计核销','completed','笔订单')}</div><div class="pantry-divider"></div><h2>正在准备的好饭</h2>${queue()}<div class="pantry-mix">${mix()}</div></aside><div class="pantry-content">${panel('窗口里的招牌好味','按核销销量排序',`<div class="food-features">${filteredSales().slice(0,3).map(s=>`<button data-dish="${s.id}"><img src="../assets/${s.image}.jpg" alt="${s.name}"/><span><b>${s.name}</b><small>${s.value} 份核销 · 余 ${s.stock} 份</small></span><strong>¥${s.price.toFixed(2)}</strong></button>`).join('')}</div>`,'food-panel')}${panel('近期预约台账','处理每一份期待',orderTable(),'table-panel')}<div class="pantry-bottom">${graphPanel('sticks',true)}${panel('经营关注','当前管理范围',attention(),'attention-panel')}</div></div></div>${overviewInfo()}</main>`
}
// 融合方案通过独立布局接入共享样本和抽屉，原10套方案保持原有实现。
if(scheme==='11'&&window.renderHybrid)layouts['11']=()=>window.renderHybrid({d,state,brand,nav,account,icon,fmt,revenue,kpi,panel,graphPanel,sales,orderTable,render,toast})
function render(){document.getElementById('app').innerHTML=layouts[scheme]();document.title=`${meta.id} ${meta.name} · 禾序设计探索`}
function show(title,content){const dialog=document.getElementById('drawer');dialog.innerHTML=`<div class="drawer-head"><div><span class="eyebrow">HEXU · INTERACTIVE PROTOTYPE</span><h2 id="drawer-title">${title}</h2></div><button class="icon-btn" data-close aria-label="关闭详情">×</button></div><div class="drawer-content">${content}</div><p class="drawer-foot">仅修改此原型的内存数据，刷新后复原。未连接真实后端。</p>`;if(!dialog.open)dialog.showModal()}
function showOrders(status=0){const list=rows().filter(o=>!status||o.status===status);show(status?labels[status]+'预约':'预约订单',`<p class="muted">当前范围示例预约，共 ${list.length} 笔</p>${list.map(o=>`<button class="drawer-order" data-order="${o.id}"><b>${o.studentName} · ${w(o.windowId).name}</b><span>${o.id} / ${o.startTime} – ${o.endTime}</span><span class="badge s${o.status}">${labels[o.status]}</span></button>`).join('')||'<p class="empty">当前筛选没有预约样本。</p>'}`)}
function showOrder(id){const o=d.orders.find(o=>o.id===id);show('预约详情',`<span class="badge s${o.status}">${labels[o.status]}</span><h3 class="detail-name">${o.studentName}</h3><dl><dt>预约号</dt><dd>${o.id}</dd><dt>窗口</dt><dd>${w(o.windowId).canteenName} · ${w(o.windowId).name}</dd><dt>取餐时段</dt><dd>11 月 5 日 ${o.startTime} — ${o.endTime}</dd><dt>菜品</dt><dd>${o.items}</dd><dt>备注</dt><dd>${o.remark}</dd><dt>订单金额</dt><dd>¥ ${o.amount.toFixed(2)}</dd></dl>${o.status<4?`<button class="primary" data-advance="${o.id}">${o.status===2?'接单并开始备餐':'标记备餐完成'} ${icon('arrow',16)}</button>`:'<p class="muted">待取餐预约需核对学生取餐码；此处只演示查看。</p>'}`)}
function module(name){if(name==='overview'){document.getElementById('drawer').close();return}if(name==='orders')return showOrders();if(name==='menu')return show('菜品与库存',filteredSales().map(s=>`<button class="drawer-order" data-dish="${s.id}"><b>${s.name}</b><span>¥${s.price.toFixed(2)} · 可售 ${s.stock} 份 · 已核销 ${s.value} 份</span>${s.stock<10?'<span class="badge s2">低库存</span>':''}</button>`).join(''));if(name==='feedback')return show('学生反馈',d.feedback.filter(f=>!state.scope||f.windowId===state.scope).map(f=>`<article class="feedback-item"><span class="pill">${w(f.windowId).name}</span><p>${f.content}</p>${f.reply?`<p class="muted">演示回复：${f.reply.replace(/[<>&]/g,'')}</p>`:`<button class="btn" data-reply="${f.id}">回复这条反馈</button>`}</article>`).join(''));if(name==='screen')show('运营数据大屏入口','<p>正式后台中，这里会在新标签页打开运营大屏并校验管理员权限。</p><p class="muted">本次设计探索仅制作管理首页，不连接或改变已有大屏。</p>')}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('visible'),2600)}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-order],[data-dish]');if(!b)return;const a=b.dataset;if(a.nav)return module(a.nav);if(a.close!==undefined)return document.getElementById('drawer').close();if(a.order)return showOrder(a.order);if(a.status)return showOrders(Number(a.status));if(a.dish){const s=d.sales.find(x=>x.id===Number(a.dish));return show(s.name,`<img class="detail-food" src="../assets/${s.image}.jpg" alt="${s.name}"/><dl><dt>窗口</dt><dd>${w(s.windowId).name}</dd><dt>单价</dt><dd>¥${s.price.toFixed(2)}</dd><dt>可售余量</dt><dd>${s.stock} 份</dd><dt>核销销量</dt><dd>${s.value} 份</dd></dl><p class="muted">正式版本的库存编辑遵循原有接口及窗口权限。</p>`)}if(a.period){state.period=Number(a.period);render();return}if(a.window){state.scope=Number(a.window);render();return}if(a.advance){const o=d.orders.find(x=>x.id===a.advance),key={2:'pending',3:'preparing',4:'ready'};d.summary[key[o.status]]--;w(o.windowId)[key[o.status]]--;o.status++;d.summary[key[o.status]]++;w(o.windowId)[key[o.status]]++;render();showOrder(o.id);toast('演示状态已更新');return}if(a.slot)return show('取餐时段 '+a.slot,`<p>每个窗口独立管理容量，当前展示已预约 / 容量。</p>${d.windows.map(x=>{const s=d.slots.find(s=>s.time===a.slot);return `<div class="drawer-order"><b>${x.name}</b><span>已约 ${s.reserved[x.id-1]} / 容量 ${s.capacity[x.id-1]}</span></div>`}).join('')}`);if(a.reply){state.replyId=Number(a.reply);return show('回复学生反馈','<form data-reply-form><label class="muted">回复内容<textarea name="reply" required maxlength="500" placeholder="写下给学生的回复…"></textarea></label><button type="submit" class="primary">保存演示回复</button></form>')}if(a.action==='search')return show('查找工作','<form data-command class="drawer-search"><input name="query" autofocus placeholder="输入预约、库存或反馈"/><button class="primary">查找</button></form>');if(a.action==='export'){const data='口径,值\n累计核销收入,'+metrics().revenue+'\n今日预约,'+metrics().todayOrders+'\n待接单,'+metrics().pending+'\n累计核销订单,'+metrics().completed;const url=URL.createObjectURL(new Blob(['\ufeff'+data],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='禾序-设计原型-Mock.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出当前范围 Mock 数据');return}if(a.action==='account')return show('管理员信息','<p>食堂管理员 · ADMIN</p><p>当前原型演示全校管理范围。真实账号、登录及退出流程在正式开发阶段保留现有权限实现。</p>');if(a.action==='explain')show('数据口径','<p>此页使用同一份 Mock：累计核销收入 ¥18,624；今日预约 186；待接单 18；备餐中 32；待取餐 14；累计核销 1,016。</p><p>近七日核销合计 ¥12,846。今日预约与累计订单、累计收入属于不同统计口径。</p>')})
document.addEventListener('change',e=>{if(e.target.matches('[data-scope]')){state.scope=Number(e.target.value);render()}})
document.addEventListener('submit',e=>{if(e.target.matches('[data-command]')){e.preventDefault();const q=new FormData(e.target).get('query')||'';if(/菜|库|餐/.test(q))module('menu');else if(/评|反馈|建议/.test(q))module('feedback');else showOrders();}if(e.target.matches('[data-reply-form]')){e.preventDefault();const feedback=d.feedback.find(f=>f.id===state.replyId);if(feedback)feedback.reply=String(new FormData(e.target).get('reply')||'');document.getElementById('drawer').close();render();toast('回复已保存在当前原型中，刷新即复原')}})
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();show('查找工作','<form data-command class="drawer-search"><input name="query" autofocus placeholder="预约、库存、反馈"/><button class="primary">查找</button></form>')}})
document.getElementById('drawer').addEventListener('click',e=>{if(e.target===e.currentTarget){const rect=e.currentTarget.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)e.currentTarget.close()}})
render()
})()
